import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group: ThreeGroup } = ctx.THREE; // fallback if needed
  const root = new Group();

  // --- Plane geometry and material ---
  const geometry = new PlaneGeometry(1, 1); // size will be scaled by texture aspect if needed
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const mesh = new Mesh(geometry, material);
  mesh.renderOrder = 0;
  root.add(mesh);

  // Load texture asynchronously
  let texture;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Text label ---
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    // Default to headline style if not specified
    const fontSize = item.typography?.fontSize ?? 39;
    const color = config.visualSpec?.colors?.paper ?? '#e8ecf2';
    const textObj = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color,
      align: 'center',
    });
    // Position text slightly above the plane
    textObj.position.set(0, 0.55, 0.01);
    root.add(textObj);
  }

  // --- Interaction handlers ---
  const timelines = [];
  let originalY = null;
  const hoverHandler = (event) => {
    if (!originalY) originalY = root.position.y;
    if (event?.type === 'enter') {
      const tl = gsap.to(root.position, {
        y: originalY + 0.15,
        duration: 0.3,
        ease: 'power3.out',
      });
      timelines.push(tl);
    } else {
      const tl = gsap.to(root.position, {
        y: originalY,
        duration: 0.2,
        ease: 'power3.out',
      });
      timelines.push(tl);
    }
  };

  const clickHandler = () => {
    const tl = gsap.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    });
    timelines.push(tl);
    ctx.emit('hub-journal.select');
  };

  root.userData.handlers = {
    hover: hoverHandler,
    click: clickHandler,
  };

  // --- Cleanup ---
  root.userData.cleanup = () => {
    material.dispose();
    geometry.dispose();
    if (texture) texture.dispose();
    timelines.forEach((t) => t.kill());
  };

  return root;
}
